// It failed with the bug and passed on the clean site. Edit freely; promote-tests won't overwrite it.

import { test, expect } from "@playwright/test";

test("product images on the home page have accessible names", async ({ page }) => {
  const pageErrors: Error[] = [];
  page.on("pageerror", (err) => pageErrors.push(err));

  await page.goto("/");
  await expect(page.getByRole("heading", { name: "Products", level: 1 })).toBeVisible();

  const productImages = page.locator('main img[src*="/img/"]');
  await expect(productImages).toHaveCount(3);

  const count = await productImages.count();
  for (let i = 0; i < count; i++) {
    await expect(productImages.nth(i)).toHaveAccessibleName(/\S+/);
  }

  expect(pageErrors).toEqual([]);
});
